import astor
import os
import sys

from collections import namedtuple
from pathlib import Path
from typing import List, Tuple

from. import utils


class SourceCode(namedtuple('SourceCode', ['filename', 'lines', 'text'])):
    def __new__(cls, filename, lines, text):
        return super().__new__(cls, filename, lines, text)

    @property
    def num_lines(self):
        return len(self.lines)

    @property
    def num_tokens(self):
        return sum([len(l.split()) for l in self.lines])

    def tokenize(self):
        tokens = []
        for line in self.lines:
            tokens.extend(line.split())
        return tokens

    @property
    def ast(self):
        return astor.to_ast(self.text)

    def show(self, output_filename=None):
        if output_filename is None:
            output_filename = self.filename
        print('=' * 79)
        print('FILE: {}'.format(output_filename))
        print('-' * 79)
        print(self.text)
        print('=' * 79)

    def save(self, output_filename=None):
        if output_filename is None:
            output_filename = self.filename
        with open(output_filename, 'w') as f:
            f.write(self.text)
